// Polyglot Rust/C++ Fibonacci
// This file is valid in both Rust and C++

#ifdef __cplusplus
#include <iostream>
#include <cstdlib>
using namespace std;
#else
// Rust code path
#endif

#ifndef __cplusplus
use std::env;
use std::process;

fn fibonacci(n: u64) -> u64 {
    match n {
        0 | 1 => 1,
        _ => {
            let mut a = 1u64;
            let mut b = 1u64;
            for _ in 2..=n {
                let temp = a + b;
                a = b;
                b = temp;
            }
            b
        }
    }
}

fn main() {
    let args: Vec<String> = env::args().collect();
    if args.len() < 2 {
        eprintln!("Usage: {} <n>", args[0]);
        process::exit(1);
    }
    let n: u64 = args[1].parse().expect("Please provide a valid number");
    println!("{}", fibonacci(n));
}
#else
// C++ code path
long long fibonacci(long long n) {
    if (n == 0 || n == 1) return 1;
    long long a = 1, b = 1;
    for (long long i = 2; i <= n; i++) {
        long long temp = a + b;
        a = b;
        b = temp;
    }
    return b;
}

int main(int argc, char* argv[]) {
    if (argc < 2) {
        cerr << "Usage: " << argv[0] << " <n>" << endl;
        return 1;
    }
    long long n = atoll(argv[1]);
    cout << fibonacci(n) << endl;
    return 0;
}
#endif
